function Get-EndpointLabel {
    [CmdletBinding()]
    param([Parameter(Position=0,ValueFromPipeline)][AllowEmptyString()][string]$Name)
    process { [pscustomobject][ordered]@{ Name=$Name; Label=$Name.ToUpperInvariant() } }
}
function Invoke-PrimaryProbe {
    [CmdletBinding()]
    param([Parameter(Position=0,Mandatory)][scriptblock]$Action,[ValidateRange(1,5)][int]$Attempts=3)
    for ($attempt=1; $attempt -le $Attempts; $attempt++) {
        try { & $Action; return } catch { if ($attempt -eq $Attempts) { throw } }
    }
}
function Invoke-SecondaryProbe {
    [CmdletBinding()]
    param([Parameter(Position=0,Mandatory)][scriptblock]$Action,[ValidateRange(1,5)][int]$Attempts=3)
    for ($attempt=1; $attempt -le $Attempts; $attempt++) {
        try { & $Action; return } catch { if ($attempt -eq $Attempts) { throw } }
    }
}
function Remove-DemoRecord {
    [CmdletBinding(SupportsShouldProcess,ConfirmImpact='High')]
    param([Parameter(Position=0,Mandatory)][ValidateNotNullOrEmpty()][string]$LiteralPath)
    if ($PSCmdlet.ShouldProcess($LiteralPath,'Remove demo record')) {
        Remove-Item -LiteralPath $LiteralPath -ErrorAction Stop
    }
}
Export-ModuleMember -Function Get-EndpointLabel,Invoke-PrimaryProbe,Invoke-SecondaryProbe,Remove-DemoRecord

