BeforeAll { Import-Module (Join-Path $PSScriptRoot '../EndpointDemo.psm1') -Force }
Describe 'EndpointDemo contracts' {
    It 'keeps pipeline order and empty strings' {
        $r=@('one','', 'two' | Get-EndpointLabel)
        $r.Count | Should -Be 3
        $r[0].Label | Should -BeExactly 'ONE'
        $r[1].Name | Should -BeExactly ''
        $r[2].Name | Should -BeExactly 'two'
    }
    It 'retries exactly three times then succeeds' {
        foreach ($command in 'Invoke-PrimaryProbe','Invoke-SecondaryProbe') {
            $state=@{ Count=0 }
            $r=& $command { $state.Count++; if($state.Count -lt 3){throw 'temporary'}; 'ok' }
            $state.Count | Should -Be 3
            $r | Should -BeExactly 'ok'
        }
    }
    It 'rethrows the last failure' {
        $state=@{ Count=0 }
        { Invoke-PrimaryProbe { $state.Count++; throw 'final' } -Attempts 2 } | Should -Throw '*final*'
        $state.Count | Should -Be 2
    }
    It 'preserves WhatIf and confirmed behavior without touching real files' {
        Mock Remove-Item {} -ModuleName EndpointDemo
        Remove-DemoRecord -LiteralPath 'synthetic' -WhatIf
        Should -Invoke Remove-Item -ModuleName EndpointDemo -Times 0 -Exactly
        Remove-DemoRecord -LiteralPath 'synthetic' -Confirm:$false
        Should -Invoke Remove-Item -ModuleName EndpointDemo -Times 1 -Exactly -ParameterFilter { $LiteralPath -eq 'synthetic' }
    }
}

